import { spawn, execFile, type ChildProcess } from 'node:child_process'
import { existsSync } from 'node:fs'
import { mkdir, readFile, writeFile, stat, symlink, copyFile, open, unlink, realpath } from 'node:fs/promises'
import { basename, dirname, join, delimiter, toNamespacedPath } from 'node:path'
import { createServer } from 'node:net'
import lockfile from 'proper-lockfile'
import { zipSync, strToU8 } from 'fflate'
import { MediaStore, mediaId, MediaConflict } from './media-store.js'
import { MEDIA_VERSIONS, MEDIA_TEMPLATES, projectSources, type MediaEngine, type MediaProject } from './media-templates.js'

interface MediaJob { id: string; kind: 'prepare' | 'preview' | 'render'; projectId?: string; revision?: number; state: 'running' | 'done' | 'failed' | 'cancelled'; stage: string; lines: string[]; url?: string; output?: string }
